-- Generated by scripts/seed_extraction_workbooks.py — do not hand-edit.
-- Platform-template SC field catalog (org_id NULL mirrors the coaches
-- template convention).
CREATE UNIQUE INDEX IF NOT EXISTS idx_cfd_template_field_key
  ON public.custom_field_definitions(entity_type, field_key) WHERE org_id IS NULL;
INSERT INTO public.custom_field_definitions
  (org_id, entity_type, field_key, field_label, field_type, admin_description,
   display_section, ai_context, extraction_instructions, extraction_signals,
   negative_signals, storage_target, sort_order, is_active)
VALUES
(NULL, 'deal', 'driver_for_new_erp', 'What is driving the need for a new ERP?', 'text', 'The forces actively pushing the company to change systems now: growth, acquisition, system end-of-life, new leadership, audit or compliance pressure, investor requirements. This is CATALYST territory: things happening that drive change. Synthesized from business_catalysts rows; not captured as its own field.', 'Business Drivers & ERP Motivation', 'The forces actively pushing the company to change systems now: growth, acquisition, system end-of-life, new leadership, audit or compliance pressure, investor requirements. This is CATALYST territory: things happening that drive change. Synthesized from business_catalysts rows; not captured as its own field.', 'Summary (generated). Underlying catalysts extracted per the Catalyst entity definition on the Core Entities tab.
Good example: Quote: ''Our PE sponsor closed two add-ons this year and wants consolidated reporting by Q3'' -> catalysts: PE acquisition activity; investor reporting mandate.
Bad example: Quote: ''Closing the books is painful'' -> pain point, not a driver. Do not write a catalyst from pain alone.', '["what''s prompting this", "why now", "we just acquired", "our PE firm wants", "QuickBooks is breaking", "new CFO came in", "auditors flagged"]'::jsonb, '["Generic dissatisfaction without a driving force (''we hate our system'') is a pain, not a catalyst. Consequences of NOT changing belong to compelling event, not here."]'::jsonb, 'business_catalysts', 10, true),
(NULL, 'deal', 'problems_to_solve', 'What problems are you trying to solve today?', 'multiselect', 'The specific operational and financial problems the prospect states they experience. RENDERS deal_pain_points; never captured as a parallel field. Each problem must be extracted as a pain point per the Pain Point entity definition.', 'Business Drivers & ERP Motivation', 'The specific operational and financial problems the prospect states they experience. RENDERS deal_pain_points; never captured as a parallel field. Each problem must be extracted as a pain point per the Pain Point entity definition.', 'Rendered list from deal_pain_points (no direct storage).
Good example: Quote: ''AP is all paper; my controller spends two days a week keying bills'' -> pain: manual AP entry, quantified 2 days/week controller time.
Bad example: Quote: ''It would be nice to have better reporting'' -> desire, route to desired_reporting, not a pain.', '["the problem is", "what kills us is", "we waste", "we can''t see", "takes us forever to", "error-prone", "manual"]'::jsonb, '["Solution wishes (''we want dashboards'') are ideal_solution, not problems. Hypothetical risks the prospect has not experienced are not pains."]'::jsonb, 'deal_pain_points', 20, true),
(NULL, 'deal', 'success_definition', 'What does success look like with a new system?', 'text', 'The prospect''s stated picture of a successful outcome after implementation: measurable targets (close in 5 days, one consolidated P&L) or capability statements (every entity manager self-serves reports). Prospect-stated only.', 'Business Drivers & ERP Motivation', 'The prospect''s stated picture of a successful outcome after implementation: measurable targets (close in 5 days, one consolidated P&L) or capability statements (every entity manager self-serves reports). Prospect-stated only.', 'Text. Keep measurable targets verbatim with numbers intact.
Good example: Quote: ''If we can close in five days and stop the Excel consolidation, that''s a win'' -> success: 5-day close; eliminate Excel consolidation.
Bad example: Rep: ''Most customers cut close time in half'' Prospect: ''mm-hm'' -> not the prospect''s statement; do not write.', '["success would be", "in a perfect world after go-live", "we''d know it worked if", "our goal is to get close down to"]'::jsonb, '["The rep''s pitch of outcomes is not the prospect''s success definition. Vendor-agnostic future plans (hiring, expansion) are catalysts, not success criteria."]'::jsonb, 'deal_analysis.ideal_solution', 30, true),
(NULL, 'deal', 'ideal_solution', 'What would your ideal solution look like?', 'text', 'The prospect''s description of the system characteristics they want: capabilities, architecture, experience. Maps to deal_analysis.ideal_solution (existing AE field); this definition hardens that extraction.', 'Business Drivers & ERP Motivation', 'The prospect''s description of the system characteristics they want: capabilities, architecture, experience. Maps to deal_analysis.ideal_solution (existing AE field); this definition hardens that extraction.', 'Text (existing home: deal_analysis.ideal_solution).
Good example: Quote: ''Ideally everything lives in one cloud system the whole team can get into from anywhere'' -> ideal: single cloud system, broad access.
Bad example: Quote: ''It must integrate with ADP or it''s a non-starter'' -> decision criterion (must-have), not ideal-solution color.', '["ideally", "what we''re looking for is", "has to have", "must be cloud", "needs to talk to"]'::jsonb, '["Hard requirements with pass/fail weight are decision criteria, not ideal-solution color. Do not duplicate: if stated as ''must have or we won''t buy'', route to decision criteria."]'::jsonb, 'deal_analysis.ideal_solution', 40, true),
(NULL, 'deal', 'required_capabilities', 'What do you need Sage Intacct to manage for you?', 'multiselect', 'The functional scope the prospect expects the new system to own: which processes move into it (GL, AP, AR, inventory, projects, budgeting). Drives module recommendation.', 'Business Drivers & ERP Motivation', 'The functional scope the prospect expects the new system to own: which processes move into it (GL, AP, AR, inventory, projects, budgeting). Drives module recommendation.', 'List of functional areas, normalized to module vocabulary where the mapping is unambiguous; otherwise keep the prospect''s words.
Good example: Quote: ''We need GL, AP, and we want inventory in there too; payroll stays with Paychex'' -> [GL, AP, Inventory]; note: payroll excluded (Paychex).
Bad example: Rep: ''You''d probably want our planning module too'' Prospect: ''maybe'' -> not confirmed scope.', '["we need it to handle", "it has to run our", "we want to move X into it", "everything except payroll"]'::jsonb, '["Capabilities they explicitly want to keep elsewhere (''payroll stays in ADP'') are exclusions", "record those in notes, not the list. Rep-suggested scope unconfirmed by the prospect is not scope."]'::jsonb, NULL, 50, true),
(NULL, 'deal', 'entity_count', 'How many entities do you have?', 'number', 'Count of distinct legal entities (corps, LLCs, partnerships, holding companies) whose books are or will be maintained. Includes the parent when it keeps its own ledger. Canonical home: deal_sizing.entity_count.', 'Company & Organizational Structure', 'Count of distinct legal entities (corps, LLCs, partnerships, holding companies) whose books are or will be maintained. Includes the parent when it keeps its own ledger. Canonical home: deal_sizing.entity_count.', 'Number. ''Parent plus N subs'' = N+1. Range given: store the stated/current number, note the range. Planned entities recorded in notes as planned, never added to the count.
Good example: Quote: ''There''s the holding company and then nine operating LLCs under it'' -> 10.
Bad example: Quote: ''We''ve got twelve locations across the Southeast'' -> locations, not entities; do not write entity_count.', '["we have N entities", "N LLCs", "N companies", "N sets of books", "the parent and N subsidiaries", "we consolidate N"]'::jsonb, '["Locations, offices, branches, stores, and warehouses are NOT entities unless stated as separate legal entities. Customers'' entities don''t count. Future entities (''we''ll spin up two more'') are planned, not current."]'::jsonb, 'deal_sizing.entity_count', 60, true),
(NULL, 'deal', 'revenue_streams', 'What revenue streams do you have?', 'multiselect', 'The distinct ways the company earns revenue (product lines, service lines, recurring vs one-time, grants for nonprofits), as described by the prospect.', 'Company & Organizational Structure', 'The distinct ways the company earns revenue (product lines, service lines, recurring vs one-time, grants for nonprofits), as described by the prospect.', 'List. Keep the prospect''s labels; note approximate mix percentages if stated.
Good example: Quote: ''About 70% is SaaS subscriptions, the rest is implementation services'' -> [SaaS subscriptions ~70%, implementation services ~30%].
Bad example: Quote: ''We sell to mid-market healthcare companies'' -> customer segment, not a revenue stream.', '["we make money from", "three lines of business", "recurring revenue from", "the rest is services", "grants and donations"]'::jsonb, '["Research-derived offerings not confirmed on a call keep source=research. Customer segments (who buys) are not revenue streams (what is sold)."]'::jsonb, NULL, 70, true),
(NULL, 'deal', 'shared_ownership', 'Is there shared ownership across entities?', 'boolean', 'Whether entities share common ownership (same parent, same owners, PE sponsor) versus independently owned entities that are merely managed together.', 'Company & Organizational Structure', 'Whether entities share common ownership (same parent, same owners, PE sponsor) versus independently owned entities that are merely managed together.', 'Boolean + ownership description in notes (who owns what).
Good example: Quote: ''Same two partners own all nine companies'' -> true; notes: two common individual owners.
Bad example: Quote: ''We do the books for all of them'' -> management relationship, not ownership; do not infer true.', '["all owned by", "same parent", "our PE firm owns", "family owns all of them", "common ownership"]'::jsonb, '["Shared management or shared back office is not shared ownership. Minority stakes described vaguely: capture the quote, mark partial."]'::jsonb, NULL, 80, true),
(NULL, 'deal', 'entity_locations_currencies', 'Where are your entities located by country and currency?', 'multiselect', 'Country (and state if stated) of each entity plus the functional currencies in play. Multi-currency is a first-order fit signal.', 'Company & Organizational Structure', 'Country (and state if stated) of each entity plus the functional currencies in play. Multi-currency is a first-order fit signal.', 'List of country/currency pairs. Normalize currency names to ISO codes (Canadian dollars -> CAD) but keep the quote verbatim.
Good example: Quote: ''Two US entities, one in Toronto that books in Canadian dollars'' -> [US/USD x2, Canada/CAD x1].
Bad example: Quote: ''We have customers in Mexico'' -> market, not an entity location.', '["entities in", "our Canadian company", "we bill in euros", "functional currency", "everything''s USD except"]'::jsonb, '["Selling INTO a country is not an entity there. Travel or remote employees abroad are not entities. Currency of customers'' payments is not necessarily a functional currency", "capture the quote and mark partial if unclear."]'::jsonb, NULL, 90, true),
(NULL, 'deal', 'shared_chart_of_accounts', 'Do you use a shared chart of accounts?', 'boolean', 'Whether entities run on one common chart of accounts versus separate charts per entity. Direct consolidation-effort signal.', 'Company & Organizational Structure', 'Whether entities run on one common chart of accounts versus separate charts per entity. Direct consolidation-effort signal.', 'Boolean + notes (e.g., ''mostly shared, two legacy entities differ'').
Good example: Quote: ''Everyone''s on the same chart except the acquisition we haven''t converted yet'' -> partial; notes: shared except one un-migrated entity.
Bad example: Quote: ''One bookkeeper does all the entities'' -> staffing, not chart structure.', '["same chart across", "one COA", "each company has its own chart", "we standardized the chart"]'::jsonb, '["Shared accounting STAFF is not a shared chart. ''Similar'' charts is partial, not true", "capture the hedge verbatim."]'::jsonb, NULL, 100, true),
(NULL, 'deal', 'interentity_accounting_today', 'How are you handling inter-entity accounting today?', 'text', 'The current mechanics of intercompany transactions: due-to/due-from tracking, eliminations, intercompany billing, and the tooling (manual journal entries, Excel, system-supported).', 'Company & Organizational Structure', 'The current mechanics of intercompany transactions: due-to/due-from tracking, eliminations, intercompany billing, and the tooling (manual journal entries, Excel, system-supported).', 'Text. Capture mechanism + tooling + pain markers verbatim.
Good example: Quote: ''Eliminations are a spreadsheet Maria maintains; intercompany loans are due-to/due-from JEs we true up quarterly'' -> manual Excel eliminations; quarterly due-to/due-from JEs.
Bad example: Quote: ''We roll everything up for the board deck'' -> reporting output, not the intercompany mechanics.', '["due to due from", "eliminations", "intercompany", "we true up between companies", "journal entries between entities", "consolidate in Excel"]'::jsonb, '["Consolidated REPORTING alone is not the intercompany process. If they say ''we don''t really do intercompany'', record that as the answer (it is a finding), not as not_discussed."]'::jsonb, NULL, 110, true),
(NULL, 'deal', 'total_users', 'How many total users will be in the system?', 'number', 'Headcount needing transactional access to the new system (entry, approval, processing). Canonical home: deal_sizing.full_users. License-driving number.', 'Users & Access', 'Headcount needing transactional access to the new system (entry, approval, processing). Canonical home: deal_sizing.full_users. License-driving number.', 'Number. If split given (e.g., ''10 in finance, 5 ops approvers''), sum for the field, keep split in notes. Ranges: store low end, note range.
Good example: Quote: ''Finance is eight, plus four project managers approving invoices, so twelve in the system'' -> 12; notes: 8 finance + 4 PM approvers.
Bad example: Quote: ''We''re a 250-person company'' -> employee count, not users; do not write.', '["N people in the system", "N users", "N seats", "the team that would touch it is N"]'::jsonb, '["Total employee count is NOT user count", "never substitute one for the other. Report-viewers stated separately route to reporting_readonly_users. Aspirational future users noted as planned."]'::jsonb, 'deal_sizing.full_users', 120, true),
(NULL, 'deal', 'reporting_readonly_users', 'How many users need access to reporting or read-only views?', 'number', 'Headcount needing only dashboards/reports without transactional access. Canonical home: deal_sizing.view_only_users.', 'Users & Access', 'Headcount needing only dashboards/reports without transactional access. Canonical home: deal_sizing.view_only_users.', 'Number. Same range/split handling as total_users.
Good example: Quote: ''Each of the nine GMs just needs to see their P&L, they won''t enter anything'' -> 9.
Bad example: Quote: ''We send the board a monthly packet'' -> distribution, not system access.', '["just need to see reports", "read-only", "dashboard access for", "the entity managers just view", "board members log in to look"]'::jsonb, '["People who RECEIVE emailed reports need no license", "only those logging in count. If unclear whether viewers transact, mark partial with the quote."]'::jsonb, 'deal_sizing.view_only_users', 130, true),
(NULL, 'deal', 'system_accounting_erp', 'What accounting or ERP system are you using today?', 'text', 'The current general ledger / ERP of record, per entity if they differ. Routes to company_systems (category=accounting, is_current=true). The displacement target.', 'Current Technology Stack', 'The current general ledger / ERP of record, per entity if they differ. Routes to company_systems (category=accounting, is_current=true). The displacement target.', 'System name(s), normalized to canonical product names (QB Enterprise vs QBO matters). Per-entity mapping in notes when entities differ. Version/edition captured when stated.
Good example: Quote: ''Eight companies on QuickBooks Enterprise, the new acquisition is still on Sage 50'' -> QuickBooks Enterprise (8 entities, current); Sage 50 (1 entity, current).
Bad example: Quote: ''We''re also looking at NetSuite'' -> competitor, route to deal_competitors.', '["we''re on", "we run", "everything''s in QuickBooks", "the Canadian entity uses", "still on Dynamics GP"]'::jsonb, '["Systems they''re EVALUATING are deal_competitors, not current systems. Systems used by their clients are not theirs. ''QuickBooks'' alone is partial until edition is known", "capture and note the edition gap."]'::jsonb, 'company_systems', 140, true),
(NULL, 'deal', 'system_payroll', 'What payroll system are you using?', 'text', 'Current payroll provider/system. Routes to company_systems (category=payroll). Usually an integration endpoint, not a displacement target.', 'Current Technology Stack', 'Current payroll provider/system. Routes to company_systems (category=payroll). Usually an integration endpoint, not a displacement target.', 'System name normalized (ADP: which product if stated, e.g., Workforce Now). Multiple providers across entities listed per entity.
Good example: Quote: ''ADP Workforce Now for everyone except the Toronto entity, that''s Ceridian'' -> ADP Workforce Now (US entities); Ceridian (Canada).
Bad example: Quote: ''Our clients mostly use ADP'' -> their clients'' systems, not theirs.', '["payroll is through", "we use ADP", "Paychex handles", "Gusto for the small companies"]'::jsonb, '["PEO relationships (TriNet, Insperity) are payroll+HR bundles", "capture as stated and note PEO. A payroll system they''re leaving is is_current=true with a note, not omitted."]'::jsonb, 'company_systems', 150, true),
(NULL, 'deal', 'system_order_management', 'What order management system do you use?', 'text', 'The system where sales orders/fulfillment live today, if any. Routes to company_systems (category=order_management).', 'Current Technology Stack', 'The system where sales orders/fulfillment live today, if any. Routes to company_systems (category=order_management).', 'System name; ''none/manual'' is a valid answer worth recording when stated.
Good example: Quote: ''Orders land in Shopify, then we rekey them into QuickBooks'' -> Shopify (order capture); note: manual rekey to accounting.
Bad example: Quote: ''We track deals in HubSpot'' -> CRM/pipeline, not order management.', '["orders come through", "we process orders in", "Shopify", "Salesforce orders", "it''s all email and spreadsheets"]'::jsonb, '["CRM used for pipeline only is not order management", "only where ORDERS are processed counts. E-commerce frontend vs OMS distinction: capture both if both named."]'::jsonb, 'company_systems', 160, true),
(NULL, 'deal', 'system_operational', 'What ticketing or operational systems are in place?', 'multiselect', 'Industry-specific operational systems running the business (field service, PM software, EHR, ticketing, POS). Routes to company_systems (category=operational). Prime integration candidates.', 'Current Technology Stack', 'Industry-specific operational systems running the business (field service, PM software, EHR, ticketing, POS). Routes to company_systems (category=operational). Prime integration candidates.', 'List of system names with the prospect''s description of role.
Good example: Quote: ''Field techs live in ServiceTitan; that''s where every job and invoice starts'' -> ServiceTitan (field service, invoice origin).
Bad example: Quote: ''We use Teams to communicate'' -> communication tool, skip.', '["we run the business on", "jobs are in", "ServiceTitan", "Procore", "our POS is", "tickets live in"]'::jsonb, '["Productivity tools (email, Office, Slack) are not operational systems unless they ARE the operational process (e.g., ''dispatch runs on a shared Outlook calendar'' is a finding worth capturing as manual-process)."]'::jsonb, 'company_systems', 170, true),
(NULL, 'deal', 'system_integrations', 'What other systems integrate with accounting today?', 'multiselect', 'Which systems currently exchange data with accounting and HOW (native sync, middleware, CSV import, manual rekey). The ''how'' is the finding. Routes to company_systems with integration_purpose.', 'Current Technology Stack', 'Which systems currently exchange data with accounting and HOW (native sync, middleware, CSV import, manual rekey). The ''how'' is the finding. Routes to company_systems with integration_purpose.', 'List: system + direction + mechanism. Mechanism normalized to: native / middleware / file import / manual.
Good example: Quote: ''Bill.com syncs natively; Shopify is a weekly CSV; everything else we key by hand'' -> Bill.com (native); Shopify (file import, weekly); rest manual.
Bad example: Quote: ''We''d want it to talk to ServiceTitan'' -> needed integration (is_needed), not a current one.', '["syncs to", "flows into QuickBooks", "we export and import", "Zapier moves", "we rekey from"]'::jsonb, '["Systems that SHOULD integrate but don''t are is_needed=true, not current integrations", "capture the gap explicitly. ''Integrated'' without mechanism is partial", "the mechanism question is the follow-up task."]'::jsonb, 'company_systems', 180, true),
(NULL, 'deal', 'fiscal_year_structure', 'What is your fiscal year structure (12 months, 13 periods, etc.)?', 'text', 'Fiscal year end and period structure (12 calendar months, 13 four-week periods, 4-4-5).', 'Financial & Accounting Foundations', 'Fiscal year end and period structure (12 calendar months, 13 four-week periods, 4-4-5).', 'Text, normalized: ''FYE <month>, <structure>''.
Good example: Quote: ''September 30 year-end, regular monthly periods'' -> FYE September, 12 months.
Bad example: Quote: ''Taxes are due in April like everyone'' -> tax filing, not fiscal structure.', '["fiscal year ends", "we''re a June year-end", "calendar year", "13 periods", "4-4-5"]'::jsonb, '["Tax year vs fiscal year can differ", "if both mentioned, capture both labeled. Busy season is a separate field", "don''t conflate."]'::jsonb, NULL, 190, true),
(NULL, 'deal', 'accounting_method', 'What accounting method do you use (cash, accrual, or both)?', 'text', 'Basis of accounting: cash, accrual, or both (e.g., accrual books, cash tax reporting, or differing by entity).', 'Financial & Accounting Foundations', 'Basis of accounting: cash, accrual, or both (e.g., accrual books, cash tax reporting, or differing by entity).', 'Enum: cash | accrual | both, + notes on the split.
Good example: Quote: ''Accrual for the operating companies, the two little holding entities are cash'' -> both; notes: accrual operating, cash holding.
Bad example: Quote: ''Cash is tight this quarter'' -> liquidity comment, not method.', '["accrual basis", "cash basis", "we book accrual but report cash for tax", "the small entities are cash"]'::jsonb, '["Cash FLOW concerns are not cash-basis accounting. If they say ''modified accrual'' or hedge, capture verbatim as both/partial with the quote."]'::jsonb, NULL, 200, true),
(NULL, 'deal', 'payroll_handling', 'How is payroll handled today?', 'text', 'The payroll PROCESS: who runs it (in-house, provider, PEO), frequency, and how it lands in the GL (auto JE, manual JE, not at all). Complements system_payroll (the tool); this is the workflow.', 'Financial & Accounting Foundations', 'The payroll PROCESS: who runs it (in-house, provider, PEO), frequency, and how it lands in the GL (auto JE, manual JE, not at all). Complements system_payroll (the tool); this is the workflow.', 'Text: operator + frequency + GL posting mechanism.
Good example: Quote: ''Biweekly through ADP; the GL entry is a manual JE our staff accountant builds from the register'' -> ADP biweekly; manual JE posting (pain marker).
Bad example: Quote: ''We use ADP'' -> tool only; that''s system_payroll, mark this partial pending process.', '["we run payroll in-house", "ADP runs it", "biweekly", "the JE comes over automatically", "we key the payroll entry"]'::jsonb, '["Don''t duplicate the system name here without the process. HR functions (benefits, onboarding) are out of scope unless they affect the GL flow."]'::jsonb, NULL, 210, true),
(NULL, 'deal', 'sales_tax_management', 'How do you manage sales tax?', 'text', 'How sales tax is calculated, collected, filed, and in which jurisdictions: engine (Avalara), manual rate tables, accountant-handled, or not applicable (exempt/services).', 'Financial & Accounting Foundations', 'How sales tax is calculated, collected, filed, and in which jurisdictions: engine (Avalara), manual rate tables, accountant-handled, or not applicable (exempt/services).', 'Text: mechanism + jurisdictions count if stated. ''Not applicable'' is a valid recorded answer.
Good example: Quote: ''We collect in seven states, rates live in a spreadsheet and our controller files monthly'' -> manual rate tables, 7 states, monthly self-filing.
Bad example: Quote: ''Our CPA does our taxes'' -> ambiguous (likely income tax); mark partial, follow-up task.', '["Avalara", "we file in N states", "rates are a spreadsheet", "our CPA files", "we''re exempt", "nexus"]'::jsonb, '["Income tax and property tax are not sales tax. Worry about FUTURE nexus is a risk/catalyst, not the current process", "capture separately."]'::jsonb, NULL, 220, true),
(NULL, 'deal', 'internal_controls', 'What does your internal control environment look like?', 'text', 'Approval thresholds, segregation of duties, audit posture (audited/reviewed/none), and known control gaps the prospect states.', 'Financial & Accounting Foundations', 'Approval thresholds, segregation of duties, audit posture (audited/reviewed/none), and known control gaps the prospect states.', 'Text. Capture thresholds with numbers verbatim; audit status normalized: audited | reviewed | compiled | none.
Good example: Quote: ''Annual audit; anything over $5k needs my sign-off, but honestly AP is one person end to end'' -> audited; $5k approval threshold; SoD gap in AP (stated).
Bad example: Quote: ''We should really have better controls'' -> aspiration; mark partial, do not record as current state.', '["we get audited", "approval over $N", "one person does everything", "segregation", "our auditors flagged"]'::jsonb, '["The prospect''s aspiration for better controls is desired state. An audit FINDING is also a catalyst candidate", "extract both (control fact here, catalyst entity separately)."]'::jsonb, NULL, 230, true),
(NULL, 'deal', 'close_duration_days', 'How long does it take you to close a month?', 'number', 'Business days from period end to close complete, current state, as stated by the prospect.', 'Month-End Close', 'Business days from period end to close complete, current state, as stated by the prospect.', 'Number (business days). Weeks x5. Calendar references (''we close by the 20th'') ~= that many calendar days, store as days with conversion noted. Ranges: midpoint, range in notes.
Good example: Quote: ''We''re usually done around the 18th'' -> ~18 calendar days (~12-13 business); note conversion.
Bad example: Quote: ''Goal is a five-day close'' -> target, route to success_definition.', '["takes us N days to close", "we close by the Nth", "close runs about N weeks", "we''re never done before the"]'::jsonb, '["TARGET close time (''we want 5 days'') is success_definition, not current state. Year-end close duration is different", "if both given, this field is the MONTHLY close, year-end in notes."]'::jsonb, NULL, 240, true),
(NULL, 'deal', 'close_bottlenecks', 'What are the biggest bottlenecks in the close process?', 'multiselect', 'The specific close steps the prospect names as slowest/most painful (intercompany eliminations, bank recs, waiting on entity submissions, manual accruals). Each is also a pain-point candidate.', 'Month-End Close', 'The specific close steps the prospect names as slowest/most painful (intercompany eliminations, bank recs, waiting on entity submissions, manual accruals). Each is also a pain-point candidate.', 'List of named bottlenecks, prospect''s words. Each quantified bottleneck links to a deal_pain_points row (pain tie-in).
Good example: Quote: ''Honestly it''s waiting on the nine entity P&Ls, then eliminations on top'' -> [entity submission lag, manual eliminations]; both pain candidates.
Bad example: Rep: ''Recs are probably the issue, right?'' Prospect: ''I guess'' -> weak confirmation; mark partial at most.', '["what slows us down is", "we always wait on", "the worst part is", "recs take forever", "chasing the entities"]'::jsonb, '["General ''close is slow'' without a named step is close_duration_days color, not a bottleneck list entry. Rep-suggested bottlenecks (''I bet eliminations hurt'') unconfirmed are nothing."]'::jsonb, NULL, 250, true),
(NULL, 'deal', 'close_delay_points', 'Where do delays typically occur?', 'text', 'WHERE in the timeline delays cluster (first week waiting on data, last week in review) and WHY, when distinct from the named bottleneck steps.', 'Month-End Close', 'WHERE in the timeline delays cluster (first week waiting on data, last week in review) and WHY, when distinct from the named bottleneck steps.', 'Text. If the prospect answers bottlenecks and delays as one answer, fill close_bottlenecks and mark this answered with the same quote rather than splitting artificially.
Good example: Quote: ''First ten days we''re just waiting on statements and entity numbers'' -> delays front-loaded: external data dependency.
Bad example: (no separate statement made) -> reuse bottleneck quote, do not invent a timeline.', '["the delay is always", "we lose the first week to", "review drags", "waiting on the bank"]'::jsonb, '["Don''t force a distinct answer if the prospect treated bottlenecks and delays as one", "duplicate-quote linking is correct, fabricated distinction is not."]'::jsonb, NULL, 260, true),
(NULL, 'deal', 'key_reports', 'What reports do you review most often today?', 'multiselect', 'The reports actually consumed on a rhythm (weekly flash, monthly P&L by entity, AR aging, job cost), as stated.', 'Reporting & Data Confidence', 'The reports actually consumed on a rhythm (weekly flash, monthly P&L by entity, AR aging, job cost), as stated.', 'List: report + cadence if stated.
Good example: Quote: ''Monthly P&L by entity for the partners, AR aging weekly'' -> [entity P&L (monthly), AR aging (weekly)].
Bad example: Quote: ''We''d love a real-time dashboard'' -> desired_reporting.', '["every week I look at", "the board gets", "we live off the", "AR aging every Monday"]'::jsonb, '["Reports they WISH existed route to desired_reporting. Reports the REP suggests they need are nothing."]'::jsonb, NULL, 270, true),
(NULL, 'deal', 'report_decision_usage', 'What are you using those reports to analyze or decide?', 'text', 'The decisions the reports drive (pricing, staffing, which entity gets capital, collections priorities). Connects reporting pain to business impact.', 'Reporting & Data Confidence', 'The decisions the reports drive (pricing, staffing, which entity gets capital, collections priorities). Connects reporting pain to business impact.', 'Text, tied to the named reports where possible.
Good example: Quote: ''The job cost report decides which service lines we keep'' -> job cost -> service-line continuation decisions.
Bad example: Quote: ''We just need good reports'' -> no decision stated; partial.', '["we use that to decide", "that tells us whether", "drives our pricing", "we staff off of"]'::jsonb, '["Generic ''to run the business'' is partial", "probe-level specificity is the SC''s FDC follow-up, not Lumen''s guess."]'::jsonb, NULL, 280, true),
(NULL, 'deal', 'data_confidence', 'How confident are you in the data you are using?', 'text', 'The prospect''s stated trust level in their numbers, with reasons (rekeying, version confusion, stale data). Low confidence statements are pain candidates.', 'Reporting & Data Confidence', 'The prospect''s stated trust level in their numbers, with reasons (rekeying, version confusion, stale data). Low confidence statements are pain candidates.', 'Text; capture hedges and qualifiers verbatim, they carry the signal.
Good example: Quote: ''By the time the P&L is done it''s three weeks old, so nobody really trusts it for decisions'' -> low confidence: staleness; pain candidate.
Bad example: Rep: ''Spreadsheets always have errors'' Prospect: (silence) -> nothing to extract.', '["I don''t fully trust", "we second-guess", "by the time we see it it''s stale", "pretty confident actually", "two versions of the truth"]'::jsonb, '["The REP casting doubt on the prospect''s data is not the prospect''s confidence statement. Confidence about a single report generalized to all data: keep it scoped to what they said."]'::jsonb, NULL, 290, true),
(NULL, 'deal', 'data_segmentation', 'How is your data segmented (classes, departments, crews, or other dimensions)?', 'multiselect', 'The dimensions they slice data by today (or wish they could): class, department, location, project, crew, fund, program. Direct dimension-fit signal.', 'Reporting & Data Confidence', 'The dimensions they slice data by today (or wish they could): class, department, location, project, crew, fund, program. Direct dimension-fit signal.', 'List of dimension names, current vs desired flagged per item.
Good example: Quote: ''Classes for location today, but we really need service line too and QB can''t do both'' -> current: location (via class); desired: service line.
Bad example: Quote: ''We have departments in the org chart'' -> org structure, not data segmentation, unless they report by it.', '["we track by class", "department-level P&L", "we can''t see it by location", "everything''s by job", "funds and programs"]'::jsonb, '["QuickBooks ''class'' abuse stories often mix current and desired", "tag each dimension as current or desired per the quote, do not blend."]'::jsonb, NULL, 300, true),
(NULL, 'deal', 'desired_reporting', 'What reporting would you ideally want to see?', 'text', 'Reports/visibility the prospect wants but lacks today. Demo-fuel and gap evidence.', 'Reporting & Data Confidence', 'Reports/visibility the prospect wants but lacks today. Demo-fuel and gap evidence.', 'List, prospect''s words, with the why when stated.
Good example: Quote: ''Consolidated cash across all nine entities, daily, without anyone building it'' -> desired: daily consolidated cash view.
Bad example: Quote: ''We get a weekly flash today'' -> current report, key_reports.', '["I wish I could see", "what I really want is", "if I could get", "we can''t produce"]'::jsonb, '["Current reports route to key_reports. The magic-wand answer routes to wishlist_insight if framed as instant-insight", "overlap is fine, link the same quote rather than duplicating text."]'::jsonb, NULL, 310, true),
(NULL, 'deal', 'excel_usage', 'What do you use Excel for today?', 'text', 'The jobs Excel performs in their finance process (consolidation, eliminations, budgets, board packs, allocations). Each is a workload-displacement and pain candidate.', 'Reporting & Data Confidence', 'The jobs Excel performs in their finance process (consolidation, eliminations, budgets, board packs, allocations). Each is a workload-displacement and pain candidate.', 'List of Excel jobs. Heavy ones link to pain rows when quantified.
Good example: Quote: ''Consolidation, eliminations, and the whole budget live in one giant workbook only Maria understands'' -> [consolidation, eliminations, budgeting]; key-person risk noted; pain candidates.
Bad example: Quote: ''I like Excel'' -> sentiment, skip.', '["everything ends up in Excel", "we consolidate in spreadsheets", "the budget is a workbook", "download to Excel and"]'::jsonb, '["Light personal use (''I keep a to-do list'') is noise", "capture process-level Excel only."]'::jsonb, NULL, 320, true),
(NULL, 'deal', 'pivot_offline_analysis', 'Are you using pivot tables or offline analysis?', 'text', 'Whether analysis happens offline after export (pivots, manual mashups), indicating the system can''t answer questions directly.', 'Reporting & Data Confidence', 'Whether analysis happens offline after export (pivots, manual mashups), indicating the system can''t answer questions directly.', 'Text/boolean + what they pivot on.
Good example: Quote: ''Every analysis starts with a GL export and a pivot'' -> true; GL-export-driven analysis.
Bad example: Quote: ''We use Excel for budgeting'' -> excel_usage, not necessarily offline analysis.', '["export and pivot", "download everything", "mash it up offline", "pivot tables on the GL dump"]'::jsonb, '["Excel usage generally is the prior field", "this is specifically the export-then-analyze pattern. If they answered it within excel_usage, link the same quote."]'::jsonb, NULL, 330, true),
(NULL, 'deal', 'charts_used', 'What types of charts and graphs do you rely on?', 'multiselect', 'Visualizations they actually use to consume data (trend lines, waterfalls, dashboards in a BI tool).', 'Reporting & Data Confidence', 'Visualizations they actually use to consume data (trend lines, waterfalls, dashboards in a BI tool).', 'List; include the tool if named (Power BI, Tableau).
Good example: Quote: ''Revenue trend and a cash waterfall in Power BI, refreshed manually'' -> [trend, waterfall]; Power BI (company_systems); manual refresh noted.
Bad example: Quote: ''Charts would be nice'' -> desired, not current.', '["we chart", "trend lines on", "our Power BI dashboard", "the board likes the waterfall"]'::jsonb, '["A BI TOOL named here also writes a company_systems row (category=operational/BI)", "do both. Wishes route to desired_reporting."]'::jsonb, NULL, 340, true),
(NULL, 'deal', 'wishlist_insight', 'If you had a magic wand, what insight would you want instantly that you do not have today?', 'text', 'The single instant-answer the prospect most wants. Highest-value demo moment per prospect; keep verbatim flavor.', 'Reporting & Data Confidence', 'The single instant-answer the prospect most wants. Highest-value demo moment per prospect; keep verbatim flavor.', 'Text, near-verbatim.
Good example: Quote: ''I want to know today, not in three weeks, which entities are bleeding cash'' -> instant entity-level cash burn visibility.
Bad example: Quote: ''Better reporting overall'' -> too generic; partial, follow-up task to sharpen.', '["if I could snap my fingers", "the one thing I''d want", "instantly know", "right now I can''t tell you"]'::jsonb, '["Do not summarize away the specificity", "the verbatim phrasing is the demo script. Multiple wishes: keep the one they flagged as THE one, others to desired_reporting."]'::jsonb, NULL, 350, true),
(NULL, 'deal', 'revenue_model', 'Can you walk me through how you make money?', 'text', 'Narrative of the commercial model: what is sold, to whom, on what terms (contracts, projects, transactions, subscriptions). The container for the billing deep-dive.', 'Revenue, Billing & Invoicing', 'Narrative of the commercial model: what is sold, to whom, on what terms (contracts, projects, transactions, subscriptions). The container for the billing deep-dive.', 'Text narrative; keep structure (X% of revenue from Y) verbatim.
Good example: Quote: ''Annual SaaS contracts billed quarterly up front, services billed monthly on completion'' -> model: annual SaaS / quarterly advance billing + monthly services billing.
Bad example: Quote: ''Business is good this year'' -> performance, not model.', '["the way it works is", "customers pay us", "we bill", "our model is", "contracts run"]'::jsonb, '["Overlaps revenue_streams (the list)", "this is the HOW narrative. Fill both from the same passage if it covers both", "link the shared quote."]'::jsonb, NULL, 360, true),
(NULL, 'deal', 'invoicing_ar_process', 'How does invoicing and accounts receivable work today?', 'text', 'End-to-end current AR mechanics: invoice trigger, creation tool, delivery, terms, collections approach, cash application.', 'Revenue, Billing & Invoicing', 'End-to-end current AR mechanics: invoice trigger, creation tool, delivery, terms, collections approach, cash application.', 'Text: trigger -> creation -> delivery -> terms -> collections -> cash app, as much as stated.
Good example: Quote: ''Invoices go out of QB when the PM marks the job done, net 30, and our office manager chases everything over 45 days from a spreadsheet'' -> trigger: PM completion; tool: QB; terms: net 30; collections: manual spreadsheet.
Bad example: Quote: ''We want automated dunning'' -> desired, route to ideal/desired.', '["we invoice when", "out of QuickBooks", "net 30", "collections is", "we apply cash by"]'::jsonb, '["Future-state desires are not the current process. Volume numbers stated here also fill deal_sizing.ar_invoices_monthly (same quote, both homes'' provenance)."]'::jsonb, NULL, 370, true),
(NULL, 'deal', 'billable_items', 'What items are billable?', 'multiselect', 'What units appear on invoices: time, materials, milestones, subscriptions, expenses passed through, change orders.', 'Revenue, Billing & Invoicing', 'What units appear on invoices: time, materials, milestones, subscriptions, expenses passed through, change orders.', 'List of billable unit types.
Good example: Quote: ''T&M for service work, fixed milestones on projects, and we pass through travel'' -> [time, materials, milestones, expense pass-through].
Bad example: Quote: ''Payroll is our biggest cost'' -> cost, not billable item.', '["we bill for", "time and materials", "milestones", "pass through expenses", "change orders get billed"]'::jsonb, '["Internal cost categories not billed to customers are out. If pass-through billing is mentioned with leakage (''we forget to bill expenses''), that is also a pain candidate."]'::jsonb, NULL, 380, true),
(NULL, 'deal', 'billing_feed_systems', 'Are any external systems feeding billing data?', 'multiselect', 'Upstream systems where billable data originates (field service, PSA, e-commerce, time tracking) and how it reaches invoicing. Routes to company_systems with integration_purpose=billing-feed; this field holds the flow description.', 'Revenue, Billing & Invoicing', 'Upstream systems where billable data originates (field service, PSA, e-commerce, time tracking) and how it reaches invoicing. Routes to company_systems with integration_purpose=billing-feed; this field holds the flow description.', 'Text: system -> mechanism -> invoicing. Systems named also write company_systems rows.
Good example: Quote: ''Hours live in Harvest, we export weekly and rekey into QB invoices'' -> Harvest -> manual weekly rekey -> QB invoicing; pain candidate.
Bad example: Quote: ''We use Slack'' -> not a billing feed.', '["billing comes out of", "time flows from", "ServiceTitan creates the invoice", "we pull hours from"]'::jsonb, '["Don''t re-list the whole tech stack", "only billable-data feeders. Manual rekey between the feeder and invoicing is the pain marker", "capture it."]'::jsonb, NULL, 390, true),
(NULL, 'deal', 'billing_rate_method', 'How are billing rates calculated?', 'text', 'How prices/rates are determined: rate cards, per-contract rates, cost-plus, role-based rates, annual escalators.', 'Revenue, Billing & Invoicing', 'How prices/rates are determined: rate cards, per-contract rates, cost-plus, role-based rates, annual escalators.', 'Text; capture escalators and exceptions verbatim.
Good example: Quote: ''Role-based rate card, but legacy clients are grandfathered all over the place'' -> role-based card + grandfathered exceptions (complexity marker).
Bad example: Quote: ''We pay techs $40/hour'' -> cost rate, not billing rate, unless cost-plus stated.', '["rate card", "cost plus N%", "by role", "each contract has its own", "rates bump N% annually"]'::jsonb, '["Discounting behavior is adjacent but distinct", "capture if volunteered, don''t probe-fill. Wage rates (what they pay) are not billing rates (what they charge) unless cost-plus links them."]'::jsonb, NULL, 400, true),
(NULL, 'deal', 'invoice_tax_handling', 'How are taxes applied to invoices?', 'text', 'How sales tax lands on invoices specifically: engine-calculated, manual rates, customer-exempt handling. The invoice-level companion to sales_tax_management.', 'Revenue, Billing & Invoicing', 'How sales tax lands on invoices specifically: engine-calculated, manual rates, customer-exempt handling. The invoice-level companion to sales_tax_management.', 'Text. If fully answered within sales_tax_management, link the same quote rather than re-asking.
Good example: Quote: ''QB applies the rate we keyed per customer, and exemption certs live in a drawer'' -> manual per-customer rates; physical cert management (pain candidate).
Bad example: (answered fully in sales tax field) -> link, don''t duplicate.', '["tax gets added", "Avalara calculates at invoice", "we look up the rate", "most customers are exempt"]'::jsonb, '["Don''t force separation from sales_tax_management when the prospect answered once", "shared quote is correct."]'::jsonb, NULL, 410, true),
(NULL, 'deal', 'revenue_recognition_method', 'What revenue recognition method do you use?', 'text', 'How revenue is recognized: point-in-time, over-time/ratable, percentage-of-completion, milestone, completed-contract, cash. 606 posture if stated.', 'Revenue, Billing & Invoicing', 'How revenue is recognized: point-in-time, over-time/ratable, percentage-of-completion, milestone, completed-contract, cash. 606 posture if stated.', 'Text normalized to method names; multiple methods per stream listed per stream.
Good example: Quote: ''SaaS is ratable over the contract, services we take as delivered'' -> ratable (SaaS); as-delivered (services).
Bad example: Quote: ''We bill annually in advance'' -> billing terms; rec method still unknown; partial.', '["we recognize", "ratably", "percentage of completion", "when the job''s done", "606", "deferred revenue"]'::jsonb, '["Billing timing is NOT recognition (''we bill quarterly up front'' says nothing about rec). If they conflate billing and rec, capture the quote, mark partial, generate the follow-up task: this is a classic FDC clarification."]'::jsonb, NULL, 420, true),
(NULL, 'deal', 'intercompany_billing', 'Is billing structured across entities or intercompany?', 'text', 'Whether entities bill each other or share customers (management fees, shared-service chargebacks, one entity invoicing on behalf of others).', 'Revenue, Billing & Invoicing', 'Whether entities bill each other or share customers (management fees, shared-service chargebacks, one entity invoicing on behalf of others).', 'Text/boolean + structure description.
Good example: Quote: ''The management company bills each LLC a 3% fee monthly'' -> true; monthly management-fee billing.
Bad example: Quote: ''We true up loans between entities'' -> intercompany accounting, not billing.', '["we bill between companies", "management fee", "entity A invoices for everyone", "chargebacks"]'::jsonb, '["Intercompany ACCOUNTING (due-to/due-from) is interentity_accounting_today", "this is customer-facing or fee billing BETWEEN entities. Related quotes can link to both when they genuinely cover both."]'::jsonb, NULL, 430, true),
(NULL, 'deal', 'invoicing_process_end_to_end', 'What does your end-to-end invoicing process look like?', 'text', 'The full walk from billable event to cash applied, including handoffs and people. The synthesis question; usually answered across several quotes.', 'Revenue, Billing & Invoicing', 'The full walk from billable event to cash applied, including handoffs and people. The synthesis question; usually answered across several quotes.', 'Text narrative assembled from quotes; every step must trace to a quote (multi-quote provenance allowed).
Good example: Quotes across the call -> ''Job completed (ServiceTitan) -> office manager exports -> rekey to QB -> email PDF -> net 30 -> manual cash app from lockbox report'' (each step quote-traced).
Bad example: Filling ''then they presumably approve it'' between two stated steps -> fabricated step; never write.', '["so the way an invoice happens is", "from there it goes to", "then accounting", "finally we apply"]'::jsonb, '["This field accumulates", "do not force completion in one call. Steps not yet described stay absent", "never bridge gaps with assumed steps."]'::jsonb, NULL, 440, true),
(NULL, 'deal', 'bank', 'What bank are you using today?', 'text', 'Primary operating bank(s). Feeds bank-feed compatibility checks.', 'Banking & Cash Management', 'Primary operating bank(s). Feeds bank-feed compatibility checks.', 'Bank name(s); per-entity mapping if stated.
Good example: Quote: ''Operating accounts at Truist, the acquisition still has its Wells accounts'' -> Truist (primary); Wells Fargo (legacy entity).
Bad example: Quote: ''Our line of credit is with a private lender'' -> credit facility, note, not operating bank.', '["we bank with", "accounts at", "Chase for operating", "the line is with"]'::jsonb, '["Lenders that are not the operating bank are credit relationships", "note separately. Personal banking references are noise."]'::jsonb, NULL, 450, true),
(NULL, 'deal', 'credit_cards', 'What credit cards are in use?', 'multiselect', 'Corporate card programs in use (Amex, bank cards, Ramp/Brex-style platforms) and roughly who carries them. Spend-management platforms named here also write company_systems rows.', 'Banking & Cash Management', 'Corporate card programs in use (Amex, bank cards, Ramp/Brex-style platforms) and roughly who carries them. Spend-management platforms named here also write company_systems rows.', 'List of card programs; cardholder scope in notes.
Good example: Quote: ''Fifteen managers carry Amex, plus the Ramp cards we just rolled out'' -> [Amex (15 holders), Ramp]; Ramp -> company_systems.
Bad example: Quote: ''We take Visa from customers'' -> merchant acceptance, not corporate cards.', '["corporate Amex", "everyone has a card", "we moved to Ramp", "bank-issued cards"]'::jsonb, '["Personal cards used for business expenses is a finding (expense-process pain marker), capture it as stated. Card PROCESSING for customers (merchant services) is a different topic."]'::jsonb, NULL, 460, true),
(NULL, 'deal', 'bank_rec_sentiment', 'How do you feel about your current bank reconciliation process?', 'text', 'The prospect''s stated experience of bank recs: effort, frequency, lag, and feeling. Sentiment fields capture the verbatim emotional register; it sells the demo moment.', 'Banking & Cash Management', 'The prospect''s stated experience of bank recs: effort, frequency, lag, and feeling. Sentiment fields capture the verbatim emotional register; it sells the demo moment.', 'Text, near-verbatim. Quantified effort links a pain row.
Good example: Quote: ''Nine entities, nine recs, my senior loses a week every month to them'' -> negative; ~1 week/month senior time; pain row linked.
Bad example: Rep: ''Recs are painful, right?'' Prospect: ''Sure'' -> partial at most; no quantification.', '["recs are a nightmare", "takes N days", "we''re always behind on", "honestly it''s fine", "my least favorite"]'::jsonb, '["The rep''s characterization (''recs must be brutal'') confirmed only by ''yeah'' is weak", "prefer the prospect''s own words, mark rep-led confirmations partial."]'::jsonb, NULL, 470, true),
(NULL, 'deal', 'cc_rec_sentiment', 'How do you feel about your current credit card reconciliation process?', 'text', 'Same as bank_rec_sentiment, scoped to corporate card recs: receipt chasing, coding, statement matching.', 'Banking & Cash Management', 'Same as bank_rec_sentiment, scoped to corporate card recs: receipt chasing, coding, statement matching.', 'Text, near-verbatim. Quantified effort links a pain row.
Good example: Quote: ''The Amex bill is 400 lines and two days of asking people what they bought'' -> negative; 2 days/month; pain row.
Bad example: Quote: ''We pay the card on time'' -> payment behavior, not the rec experience.', '["chasing receipts", "coding the Amex bill takes", "cardholders never submit", "the statement rec is"]'::jsonb, '["Expense-report pain overlaps expense_report_process", "if one quote covers both, link it to both rather than splitting the sentence."]'::jsonb, NULL, 480, true),
(NULL, 'deal', 'ap_recurring_process', 'How does your payables process work for rent, utilities, and other recurring expenses?', 'text', 'How recurring/predictable payables are handled: auto-pay, memorized transactions, manual entry each cycle.', 'Payables, Purchasing & Expenses', 'How recurring/predictable payables are handled: auto-pay, memorized transactions, manual entry each cycle.', 'Text: mechanism per recurring category as stated.
